S = "motu-avb"
# MOTU AVB Datastore API: PATCH /datastore/<path> with the form field json={"value": v},
# percent-encoded; paths count from 0.


def req(command, input, method, target, body=None, **extra):
    request = {"method": method, "target": target}
    if body is not None:
        request["body"] = body
    V.append({"spec": S, "command": command, "input": input, "expect_request": request, **extra})


